# Rebuilds the data block inside index.html from the three CSV files kept
# alongside this script. Run it after editing any of them:
#
#   Rscript makedata.R          (from a terminal, any folder)
#   source("makedata.R")        (from R, with this folder as working directory)
#
# It rewrites only the lines between
#   // ---- DATA (generated by makedata.R) ----
#   // ---- END DATA ----
# in index.html; everything else in the page is left alone.
#
# THE DATA FILES (all in this folder)
#
#   payscale.csv   grade, year, salary
#                  The current academic salary scale. Replace the lot when a
#                  new scale comes in; every row should carry the same year.
#
#   annualpayincrease.csv   year, pay_rise_pct
#                  The across-the-board rise in that year's collective
#                  agreement, as a percentage (2 means 2%). The first year is
#                  the base, so its rise is ignored.
#
#   averagepay.csv year, academic, professional
#                  Total salary cost / total FTE for each staff group, from the
#                  University's annual reports. Leave a cell blank if missing.
#
#   indexes.csv    quarter, cpi, lci
#                  Published Stats NZ figures ONLY, one row per quarter, quarter
#                  written like 2026Q2 (Q1 = March, Q2 = June, ...).
#                    cpi  Consumers Price Index, all groups (CPIQ.SE9A)
#                    lci  Labour Cost Index, all sectors, salary and wage rates
#                         (LCIQ.SD53Z9), base June 2017 quarter = 1000
#                  When Stats NZ releases a quarter, add a row (or fill a blank
#                  cell) and rerun. Do not type projections here; they come from
#                  assumed_rates below.
#
# The only things you should need to edit in this script are assumed_rates
# and, rarely, the wording of average_note.

suppressPackageStartupMessages({
  library(tidyverse)
  library(jsonlite)
})

# Annual % rates used to project each index past its last published quarter.
# Each entry reads "this rate up to the end of this year", so
#   c("2026" = 4, "2028" = 3)
# means 4% a year to the end of 2026, then 3% a year to the end of 2028.
# Projections run to the last year named. The note shown on the webpage is
# written from these numbers, so it always says what was actually assumed.
assumed_rates <- list(
  cpi = c("2026" = 4, "2028" = 3),
  lci = c("2028" = 3)
)

average_note <- paste("Total salary cost divided by total FTE, both reported in",
                      "Waipapa Taumata Rau/University of Auckland annual reports.")

months <- c("Mar", "Jun", "Sep", "Dec")

# ---------------------------------------------------------------- read

# the folder this script lives in, however it was run
here <- local({
  f <- sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE))
  f <- gsub("~+~", " ", f, fixed = TRUE)  # Rscript's encoding of spaces
  if (length(f)) return(dirname(normalizePath(f)))
  for (i in rev(seq_len(sys.nframe()))) {
    o <- sys.frame(i)$ofile
    if (!is.null(o)) return(dirname(normalizePath(o)))
  }
  getwd()
})
path <- function(f) file.path(here, f)

payscale <- read_csv(path("payscale.csv"), col_types = "cii")
payrise  <- read_csv(path("annualpayincrease.csv"), col_types = "id") %>% arrange(year)
avgpay   <- read_csv(path("averagepay.csv"), col_types = "iii") %>% arrange(year)
indexes  <- read_csv(path("indexes.csv"), col_types = "cdd") %>%
  separate_wider_regex(quarter, c(year = "\\d{4}", "Q", q = "[1-4]")) %>%
  mutate(year = as.integer(year), q = as.integer(q)) %>%
  arrange(year, q)

stopifnot(length(unique(payscale$year)) == 1)
if (!payscale$year[1] %in% payrise$year[!is.na(payrise$pay_rise_pct)])
  stop("annualpayincrease.csv needs a pay_rise_pct for ", payscale$year[1], ", the payscale year")

# ---------------------------------------------------------------- project

# One index: published values, then quarters projected from assumed_rates.
# Returns the full quarterly series plus the last published quarter and the
# sentence describing the projection.
project <- function(series) {
  rates <- assumed_rates[[series]]
  through <- as.integer(names(rates))
  pub <- indexes %>% select(year, q, value = all_of(series)) %>% filter(!is.na(value))

  # blanks are fine at the end (not yet published), not in the middle
  n_expected <- (last(pub$year) - first(pub$year)) * 4 + last(pub$q) - first(pub$q) + 1
  if (nrow(pub) != n_expected) stop(series, " has a gap in indexes.csv")

  last_y <- last(pub$year); last_q <- last(pub$q)
  future <- expand_grid(year = last_y:max(through), q = 1:4) %>%
    filter(year > last_y | q > last_q)
  rate_for <- function(y) rates[which(through >= y)[1]]
  growth <- (1 + sapply(future$year, rate_for) / 100)^(1 / 4)
  future$value <- last(pub$value) * cumprod(growth)

  # describe only the rates that actually apply to the projected quarters
  used <- rates[through >= if (nrow(future)) first(future$year) else Inf]
  pct <- function(r) paste0(format(r, drop0trailing = TRUE), "%")
  note <- if (length(used) == 0) "" else if (length(used) == 1) {
    paste0("After that, an annual rate of ", pct(used), " is assumed.")
  } else {
    steps <- paste0(pct(head(used, -1)), " to the end of ", head(names(used), -1))
    steps[1] <- sub(" to", " is assumed to", steps[1])
    paste0("After that, an annual rate of ", paste(steps, collapse = ", then "),
           ", then ", pct(last(used)), ".")
  }

  list(values = bind_rows(pub, future),
       actual = paste0(last_y, "-", months[last_q]),
       note = note)
}

cpi <- project("cpi")
lci <- project("lci")

# one entry per year, four values each: Mar, Jun, Sep, Dec
byyear <- function(df) {
  df %>%
    group_by(year) %>%
    filter(n() == 4) %>%
    summarise(v = list(round(value, 4)), .groups = "drop") %>%
    with(setNames(v, as.character(year)))
}

average_list <- function(col) {
  keep <- !is.na(avgpay[[col]])
  setNames(as.list(avgpay[[col]][keep]), as.character(avgpay$year[keep]))
}

# ---------------------------------------------------------------- write

paydata <- list(
  payscaleYear = payscale$year[1],
  payscale = payscale %>% select(grade, salary),
  payIndex = payrise %>%
    filter(!is.na(pay_rise_pct)) %>%
    mutate(index = round(100 * cumprod(1 + replace(pay_rise_pct, 1, 0) / 100), 6)) %>%
    with(setNames(as.list(index), as.character(year))),
  months = months,
  cpi = byyear(cpi$values),
  lci = byyear(lci$values),
  actualThrough = list(cpi = cpi$actual, lci = lci$actual),
  projectionNote = list(cpi = cpi$note, lci = lci$note),
  averagePay = list(academic = average_list("academic"),
                    professional = average_list("professional")),
  averageNote = average_note
)

json <- toJSON(paydata, auto_unbox = TRUE, digits = NA, pretty = TRUE)

page <- readLines(path("index.html"), encoding = "UTF-8")
start <- grep("^// ---- DATA \\(generated by makedata.R\\) ----$", page)
end <- grep("^// ---- END DATA ----$", page)
stopifnot(length(start) == 1, length(end) == 1, start < end)

page <- c(page[1:start],
          paste0("const PAYDATA = ", json, ";"),
          page[end:length(page)])
writeLines(page, path("index.html"), useBytes = TRUE)

cat("updated index.html\n",
    "  CPI published to ", cpi$actual, ", LCI published to ", lci$actual, "\n",
    "  payscale ", paydata$payscaleYear, ", pay rises to ", last(names(paydata$payIndex)), "\n",
    sep = "")
